// Private media Blob URLs are trusted only when generated by the authenticated
// media API. Keep this standalone so public presentation never imports API auth.
const privateMediaObjectUrls = new Set<string>();

export function registerPrivateMediaUrl(url:string):void {
 privateMediaObjectUrls.add(url);
}

export function releasePrivateMediaUrl(url:string):void {
 if(privateMediaObjectUrls.delete(url))URL.revokeObjectURL(url);
}

export function isPrivateMediaUrl(url:string):boolean {
 return privateMediaObjectUrls.has(url);
}

/** Closing a session must invalidate and revoke every authenticated preview. */
export function clearPrivateMediaUrls():void {
 for(const url of privateMediaObjectUrls)URL.revokeObjectURL(url);
 privateMediaObjectUrls.clear();
}
